mapper.select:
SELECT dept_code AS deptCode, dept_name AS deptName, SUM(NVL(total_visits, 0)) AS totalVisits, ROUND(AVG(NVL(appointment_rate, 0)), 2) || '%' AS appointmentRate, SUM(NVL(visit_count, 0)) AS visitCount, ROUND(AVG(NVL(exam_rate, 0)), 2) || '%' AS examRate, ROUND(AVG(NVL(efficiency, 0)), 2) AS efficiency, SUM(NVL(effective_units, 0)) AS effectiveUnits, SUM(NVL(total_units, 0)) AS totalUnits, SUM(NVL(famous_expert, 0)) AS famousExpert, SUM(NVL(special_expert, 0)) AS specialExpert, SUM(NVL(known_expert, 0)) AS knownExpert, SUM(NVL(expert_a, 0)) AS expertA, SUM(NVL(expert_b, 0)) AS expertB, SUM(NVL(ordinary, 0)) AS ordinary, SUM(NVL(unit_famous_effective, 0)) AS unitFamousEffective, SUM(NVL(unit_famous_total, 0)) AS unitFamousTotal, SUM(NVL(unit_special_effective, 0)) AS unitSpecialEffective, SUM(NVL(unit_special_total, 0)) AS unitSpecialTotal, SUM(NVL(unit_known_effective, 0)) AS unitKnownEffective, SUM(NVL(unit_known_total, 0)) AS unitKnownTotal, SUM(NVL(unit_a_effective, 0)) AS unitAEffective, SUM(NVL(unit_a_total, 0)) AS unitATotal, SUM(NVL(unit_b_effective, 0)) AS unitBEffective, SUM(NVL(unit_b_total, 0)) AS unitBTotal, SUM(NVL(unit_ordinary_effective, 0)) AS unitOrdinaryEffective, SUM(NVL(unit_ordinary_total, 0)) AS unitOrdinaryTotal, COUNT(DISTINCT stat_date) AS daysCount, COUNT(1) AS recordCount FROM TR_OUTP_OP WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_code = #{deptCode}
GROUP BY dept_code, dept_name ORDER BY totalVisits DESC
